      var confirmColor = 'background:linear-gradient(135deg,#4f46e5,#818cf8);color:#fff;';
      var cancelText = options.cancelButtonText || 'Cancel';
      var cancelColor = 'background:#252542;color:#f1f5f9;';
      var cb = function (value) { resolve({ isConfirmed: value, isDismissed: !value, value: value ? true : undefined }); };
      if (options.showCancelButton) {
        btnRow.appendChild(mkBtn(cancelText, cancelColor, function () { cb(false); }));
        btnRow.appendChild(mkBtn(confirmText, confirmColor, function () { cb(true); }));
      } else {
        btnRow.appendChild(mkBtn(confirmText, confirmColor, function () { cb(true); }));
      }
